#!/usr/bin/env bash
# Write .generated/env.sh with absolute -F paths for DistSSHRun / git SSH.
# Called by docker-ssh and apple-container-ssh up.sh after ssh_config is final.
# Path + flags only — never private key material (gitleaks / gitignore).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
GEN="${ROOT}/.generated"
SSH_CONFIG="${GEN}/ssh_config"
ENV_FILE="${GEN}/env.sh"

if [[ ! -f "${SSH_CONFIG}" ]]; then
  echo "missing ${SSH_CONFIG}; run up.sh first" >&2
  exit 1
fi

umask 077
cat > "${ENV_FILE}" <<EOF
# Generated by docker-ssh / apple-container up.sh. Not for commit.
DISTRIBUTED_SSH_OPTS="-F ${SSH_CONFIG} -o RequestTTY=no"
GIT_SSH_COMMAND="ssh -F ${SSH_CONFIG} -o RequestTTY=no"
EOF

echo "Wrote ${ENV_FILE}"
